Run with a subcommand to perform a single maneuver. The service persists state
between invocations; get a fresh observation before choosing the next action.
"""
import sys, json, math
import numpy as np
sys.path.insert(0, "/opt/tools")
from rcb_client import Robot, EpisodeOver

DOWN = np.array([0.0, -math.sqrt(0.5), math.sqrt(0.5), 0.0])
# Tool +z points toward +x; the jaw span remains across world y.
SIDE = np.array([0.5, -0.5, 0.5, -0.5])
# Tool +z points toward +y, with jaw span along world x.
SIDE_Y = np.array([math.sqrt(0.5), -math.sqrt(0.5), 0.0, 0.0])
# Depth-derived scene coordinates, env-local metres (x forward, y left, z up).
MUG_UP = np.array([0.435, 0.302, 0.063])
MUG_SIDE = np.array([0.559, 0.281, 0.063])
BOWL = np.array([0.320, 0.100, 0.070])
BIN = np.array([0.548, -0.265, 0.053])
CUP_A = np.array([0.418, 0.247, 0.058])
CUP_B = np.array([0.567, 0.263, 0.058])

def connect():
    r = Robot()
    return r

def now(r):
    o = r.get_obs(video="none")
    a = np.asarray(o.meta["proprio"]["now"], dtype=float)
    return o, a

def move(r, xyz, grip=None, q=DOWN, spacing=0.012):
    """Linear Cartesian motion with dense rows for the differential IK servo."""
    o, a = now(r)
    start = a[8:11]
    qstart = a[11:15].copy()
    g = float(a[15] > 0.5) if grip is None else float(grip)
    xyz = np.asarray(xyz, dtype=float)
    res = None
    for _ in range(20):
        delta = xyz-start
        dist = float(np.linalg.norm(delta))
        q0 = qstart / np.linalg.norm(qstart)
        q1 = np.asarray(q,dtype=float) / np.linalg.norm(q)
        if float(np.dot(q0,q1)) < 0: q1=-q1
        angle = 2*math.acos(float(np.clip(np.dot(q0,q1),-1,1)))
        if dist <= 0.006 and angle <= 0.015: break
        n = max(1, int(math.ceil(dist/spacing)), int(math.ceil(angle/0.08)))
        k = min(n, 48)
        rows=[]
        for i in range(1,k+1):
            f=i/n
            qi=(1-f)*q0+f*q1;qi/=np.linalg.norm(qi)
            rows.append([*(start+delta*f), *qi, g])
        res = r.submit("ee_pose", np.asarray(rows, dtype=np.float32), video="none")
        print("move", np.round(xyz,3).tolist(), "rows",len(rows),"meta",json.dumps({k:res.meta.get(k) for k in ["done","reason","plan","clipped","time_left_s"]}))
        if res.done: return res
        if k >= n: break
        o,a=now(r);start=a[8:11];qstart=a[11:15].copy()
    return res

def hold(r, xyz, grip, count=6, q=DOWN):
    row = np.array([[*xyz, *q, float(grip)] for _ in range(count)], dtype=np.float32)
    res = r.submit("ee_pose", row, video="none")
    print("hold", grip, "meta",json.dumps({k:res.meta.get(k) for k in ["done","reason","plan","time_left_s"]}))
    return res

def state(r):
    o,a=now(r)
    print("now",np.round(a,4).tolist(),"meta",json.dumps({k:o.meta.get(k) for k in ["step","sim_time_s","time_left_s","done","reason"]}))
    for c,img in o.last.items():
        from PIL import Image
        Image.fromarray(img).save("/app/output/current_"+c+".png")
    return o,a

if __name__ == "__main__":
    r=connect()
    cmd=sys.argv[1] if len(sys.argv)>1 else "state"
    if cmd=="state": state(r)
    elif cmd=="move": move(r,[float(x) for x in sys.argv[2:5]])
    elif cmd=="open":
        o,a=now(r); hold(r,a[8:11],0,count=6)
    elif cmd=="close":
        o,a=now(r); hold(r,a[8:11],1,count=20)
    elif cmd=="mugup_pre": move(r,[*MUG_UP[:2],0.205],0)
    elif cmd=="mugup_down": move(r,MUG_UP,0)
    elif cmd=="mugside_pre": move(r,[*MUG_SIDE[:2],0.205],0)
    elif cmd=="mugside_down": move(r,MUG_SIDE,0)
    elif cmd=="bowl_pre": move(r,[*BOWL[:2],0.205],0)
    elif cmd=="bowl_down": move(r,BOWL,0)
    elif cmd=="bin_above": move(r,[*BIN[:2],0.30],0)
    elif cmd=="bin_release":
        o,a=now(r); p=a[8:11].copy(); p[2]=0.19; move(r,p,0); hold(r,p,0,8)
    elif cmd=="lift":
        o,a=now(r); p=a[8:11].copy(); p[2]=float(sys.argv[2]) if len(sys.argv)>2 else 0.28; move(r,p,1)
    elif cmd=="open_wait":
        o,a=now(r); hold(r,a[8:11],0,count=20,q=a[11:15])
    elif cmd=="hover": move(r,[0.30,0.30,0.30],0)
    elif cmd=="side_rotate": move(r,[0.30,0.30,0.30],0,q=SIDE)
    elif cmd=="side_pre": move(r,[0.30,0.30,0.10],0,q=SIDE)
    elif cmd=="side_grasp": move(r,[0.423,0.30,0.10],0,q=SIDE)
    elif cmd=="side_close":
        o,a=now(r); hold(r,a[8:11],1,count=20,q=SIDE)
    elif cmd=="side_lift":
        o,a=now(r); p=a[8:11].copy();p[2]=0.28;move(r,p,1,q=SIDE)
    elif cmd=="y_hover": move(r,[0.41,0.18,0.30],0)
    elif cmd=="clear_up": move(r,[0.4168,0.3031,0.30],0)
    elif cmd=="y_rotate": move(r,[0.41,0.18,0.30],0,q=SIDE_Y)
    elif cmd=="y_pre": move(r,[0.41,0.22,0.10],0,q=SIDE_Y)
    elif cmd=="y_grasp": move(r,[0.41,0.30,0.10],0,q=SIDE_Y)
    elif cmd=="y_close":
        o,a=now(r);hold(r,a[8:11],1,count=20,q=SIDE_Y)
    elif cmd=="y_lift":
        o,a=now(r);p=a[8:11].copy();p[2]=0.28;move(r,p,1,q=SIDE_Y)
    elif cmd=="cupA_hover": move(r,[*CUP_A[:2],0.30],0,q=DOWN)
    elif cmd=="cupA_pre": move(r,[*CUP_A[:2],0.19],0,q=DOWN)
    elif cmd=="cupA_grasp": move(r,CUP_A,0,q=DOWN)
    elif cmd=="cupA_close":
        o,a=now(r);hold(r,a[8:11],1,count=20,q=DOWN)
    elif cmd=="bowl_hover": move(r,[0.20,0.10,0.28],0,q=DOWN)
    elif cmd=="bowl_rotate": move(r,[0.20,0.10,0.28],0,q=SIDE)
    elif cmd=="bowl_inside": move(r,[0.32,0.10,0.105],0,q=DOWN)
    elif cmd=="bowl_inside_deep": move(r,[0.32,0.10,0.082],0,q=DOWN)
    elif cmd=="bowl_edge_pre": move(r,[0.504,0.0745,0.22],0,q=DOWN)
    elif cmd=="bowl_edge_grasp": move(r,[0.504,0.0745,0.12],0,q=DOWN)
    elif cmd=="bowl_edge_close":
        o,a=now(r);hold(r,a[8:11],1,count=20,q=DOWN)
    elif cmd=="bowl_inside_close":
        o,a=now(r);hold(r,a[8:11],1,count=20,q=DOWN)
    elif cmd=="bowl_pre": move(r,[0.20,0.10,0.07],0,q=SIDE)
    elif cmd=="bowl_grasp": move(r,BOWL,0,q=SIDE)
    elif cmd=="bowl_close":
        o,a=now(r);hold(r,a[8:11],1,count=20,q=SIDE)
    else: raise SystemExit("unknown command")
